141	        var cursorTextures = new Dictionary<CursorType, Texture2D>
142	        {
143	            [CursorType.Default] = content.Load<Texture2D>("Mouse sprites/Triangle Mouse icon 1"),
144	            [CursorType.Pointer] = content.Load<Texture2D>("Mouse sprites/Triangle Mouse icon 2"),
145	            [CursorType.Hand] = content.Load<Texture2D>("Mouse sprites/Catpaw Mouse icon"),
146	        };
147	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
148	
149	        // Load the requested level so there is something to edit (same path as the play screen).
150	        var requestedLevel = screenController.Game.Services.GetService(typeof(RequestedLevelComponent)) as RequestedLevelComponent;
151	        if (requestedLevel != null)
152	        {
153	            _world.Publish(new LoadLevelRequest(requestedLevel.LevelIdentifier));
154	            screenController.Game.Services.RemoveService(typeof(RequestedLevelComponent));
155	        }
156	    }
157	
158	    private SequentialSystem<GameState> CreateUpdateSystem()
159	    {
160	        var debugDir = PlatformServices.Current.GetEnvironmentVariable("MONODREAMS_DEBUG_DIR")
161	            ?? PlatformServices.Current.CombinePath(PlatformServices.Current.BaseDirectory, "debug");
162	        var inputMappingSystem = new InputMappingSystem(_world);
163	        var actionMap = new Dictionary<string, AInputState>
164	        {
165	            ["Up"] = InputState.Up, ["Down"] = InputState.Down,
166	            ["Left"] = InputState.Left, ["Right"] = InputState.Right,
167	            ["Jump"] = InputState.Jump, ["Grab"] = InputState.Grab,
168	            ["Orb"] = InputState.Orb, ["Exit"] = InputState.Exit,
169	            ["Interact"] = InputState.Interact,
170	            ["Editor"] = InputState.Editor, ["Delete"] = InputState.Delete,
171	            ["Undo"] = InputState.Undo, ["Redo"] = InputState.Redo,
172	        };
173	
174	        var replaySystem = InputReplaySystem.TryLoad(debugDir, actionMap, _game);
175	
176	        // The headless editor-op channel (Wave 5): when an editor_op_plan.json is present, a scripted
177	        // cursor (no real mouse) drives the real editor systems. The driver injects CursorInputComponent
178	        // state that CursorInputSystem.SkipHardwareRead must leave untouched.
179	        var editorOpPlan = EditorOpPlan.TryLoad(debugDir);
180	        var cursorInputSystem = new CursorInputSystem(_world);
181	
182	        ISystem<GameState> inputSystems;
183	        if (replaySystem != null)
184	        {
185	            inputMappingSystem.SkipHardwareRead = true;
186	            if (editorOpPlan != null) cursorInputSystem.SkipHardwareRead = true;
187	            inputSystems = new SequentialSystem<GameState>(
188	                cursorInputSystem, replaySystem, inputMappingSystem);
189	        }
190	        else if (editorOpPlan != null)
191	        {
192	            // Editor-op channel without a keyboard replay: still skip the hardware cursor read so the
193	            // injected state survives, and run input mapping normally (the channel drives the cursor).
194	            cursorInputSystem.SkipHardwareRead = true;
195	            inputSystems = new SequentialSystem<GameState>(cursorInputSystem, inputMappingSystem);
196	        }
197	        else
198	        {
199	            inputSystems = new ParallelSystem<GameState>(_parallelRunner,
200	                cursorInputSystem, inputMappingSystem);
201	        }
202	
203	        var promptFont = _content.Load<BitmapFont>("Fonts/PPMondwest-Regular-fnt");
204	
205	        var blenderParser = new BlenderLevelParserSystem(_world, _content, _camera);
206	        blenderParser.SetDrawLayerMap(_layers);
207	
208	        var entitySpawnSystem = new EntitySpawnSystem(_world, _content, _renderTargets);
209	        entitySpawnSystem.RegisterEntityFactory("Tile", new TileEntityFactory(_layers));
210	        entitySpawnSystem.RegisterEntityFactory("Wall", new WallEntityFactory(_content, _layers));
211	        entitySpawnSystem.RegisterEntityFactory("Player", new PlayerEntityFactory(_content, _layers));
212	        entitySpawnSystem.RegisterEntityFactory("Enemy", new NPCEntityFactory(_content, _layers));
213	
214	        // Level loading + native-scene loading. SceneReaderSystem handles LoadSceneRequest (separate
215	        // from LoadLevelRequest) so the toolbar's Load (Wave 4b) reconstructs a native scene here.
216	        var levelLoadSystems = new SequentialSystem<GameState>(
217	            new LevelLoadRequestSystem(_world, _content),
218	            blenderParser,
219	            new LDtkTileParserSystem(_world, _content),
220	            new LDtkEntityParserSystem(_world),
221	            entitySpawnSystem,
222	            new SceneReaderSystem(_world, _sceneSerializer, _content));
223	
224	        // Game logic + physics — FROZEN in Edit (the §4 matrix). Wrapping the whole block in one
225	        // Freeze gate is equivalent to wrapping each system: the gate skips the child Update entirely.
226	        var logicSystems = new GatedSystem(new SequentialSystem<GameState>(
227	            new MovementSystem(_world, _parallelRunner),
228	            new OrbSystem(_world),
229	            new StopMotionEffectSystem(_world),
230	            new TransformVelocitySystem(_world, _parallelRunner),
231	            new TransformCollisionDetectionSystem<CollisionMessage>(_world, GameCollisionHelper.Create),
232	            new TransformPhysicalCollisionResolutionSystem(_world),
233	            new TransformCommitSystem(_world, _parallelRunner),
234	            new TextUpdateSystem(_world),
235	            new NPCInteractionSystem(_world),
236	            new ZoneDialogueTriggerSystem(_world),
237	            new DialogueSystem(
238	                _world,
239	                _content.Load<Texture2D>("Dialouge UI/dialog box medium"),
240	                _content.Load<BitmapFont>("Fonts/PPMondwest-Regular-fnt"),
241	                _content.Load<Texture2D>("Dialouge UI/dialog box character finished talking click to continue indicator - spritesheet")
242	                    .Crop(new Rectangle(96, 0, 16, 16), _graphicsDevice),
243	                _viewportManager.VirtualWidth,
244	                _viewportManager.VirtualHeight,
245	                _layers.GetDepth(GameDrawLayer.DialogueUI),
246	                InputState.Interact,
247	                InputState.Up,
248	                InputState.Down,
249	                new[]
250	                {
251	                    _content.Load<YarnProgram>("Dialogues/hello_world"),
252	                    _content.Load<YarnProgram>("Dialogues/boldo")
253	                },
254	                nameof(EntityType.Interface))
255	        ), EditTimeBehavior.Freeze);
256	
257	        // HierarchySystem stays LIVE in Edit (RunNormally) so editor transform edits propagate to
258	        // world space the same frame — explicitly NOT wrapped in a Freeze gate.
259	        var hierarchySystem = new HierarchySystem(_world);
260	
261	        // Camera-follow FREEZES in Edit (the editor drives the camera); RunNormally in Play.
262	        var cameraFollowSystem = new GatedSystem(new CameraFollowSystem(_world, _camera), EditTimeBehavior.Freeze);
263	
264	        var cursorLateUpdateSystem = new CursorPositionSystem(_world, _camera, _viewportManager);
265	
266	        // Editor systems — pre-registered, RunNormally, Edit-guarded internally (inert in Play).
267	        var modeToggle = new EditorModeToggleSystem(state => InputState.Editor.JustPressed());
268	        var editorCommands = new EditorCommandSystem(
269	            _world, _history, _sceneSerializer,
270	            deleteRequested: _ => InputState.Delete.JustPressed(),
271	            undoRequested: _ => InputState.Undo.JustPressed(),
272	            redoRequested: _ => InputState.Redo.JustPressed());
273	
274	        // The shared gizmo-state entity (single instance): the toolbar mutates it, GizmoSystem reads it.
275	        _gizmoState = _world.CreateEntity();
276	        _gizmoState.Set(GizmoStateComponent.Default);
277	
278	        // The transform gizmo: reads SelectedComponent, draws handles + selection outline, drives a
279	        // drag into ONE undo step via the SAME _history (drag-coalescing). Runs BEFORE HierarchySystem
280	        // so an edit propagates to world space the same frame.
281	        var gizmoSystem = new GizmoSystem(_world, _camera, _history);
282	
283	        // The engine-native toolbar (HUD target). Build the buttons, wire the dispatch to the screen's
284	        // own SAME _history / _sceneSerializer / _camera / _layers, and register the click system.
285	        new EditorToolbarBuilder(_world, promptFont).Build(viewportManager: _viewportManager);
286	        var toolbarSystem = new ToolbarSystem(_world, DispatchToolbarAction);
287	        var buttonMeshPrep = new ButtonMeshPrepSystem(_world);
288	
289	        // The headless editor-op driver (Wave 5): scripted cursor + RunMode toggle + toolbar actions,
290	        // no real mouse. It is registered ONLY when a plan is present (zero cost in a normal run). It
291	        // runs AFTER CursorPositionSystem so its injected world/virtual cursor is the final word the
292	        // gizmo/toolbar read, and it holds the session open (requestExit fires only when its ops drain),
293	        // so the input-replay channel's auto-exit-on-drain can't kill the editor-op run early.
294	        EditorOpReplaySystem editorOpDriver = null;
295	        if (editorOpPlan != null)
296	        {
297	            editorOpDriver = new EditorOpReplaySystem(_world, editorOpPlan, DispatchToolbarAction, _game.Exit);
298	            // Hold the session open: if a keyboard replay is also present, suppress its auto-exit-on-drain
299	            // until the editor-op plan finishes, so the editor-op driver owns the exit.
300	            if (replaySystem != null)
301	                replaySystem.SuppressAutoExit = () => !editorOpDriver.IsComplete;
302	        }
303	
304	        var systems = new List<ISystem<GameState>>
305	        {
306	            inputSystems,
307	            modeToggle,        // flips RunMode (works in both modes)
308	            levelLoadSystems,  // message-driven; loads game level + native scenes
309	            logicSystems,      // FROZEN in Edit
310	            editorCommands,    // delete / undo / redo (Edit-guarded)
311	            gizmoSystem,       // selection gizmo + drag → one undo step (Edit-guarded); BEFORE Hierarchy
312	            hierarchySystem,   // LIVE in Edit (propagates the gizmo edit this frame)
313	            cameraFollowSystem,// FROZEN in Edit
314	            buttonMeshPrep,    // toolbar button outline meshes (HUD) — rebuilt every frame
315	            toolbarSystem,     // toolbar clicks + visibility (AFTER buttonMeshPrep so Play-hide sticks)
316	            cursorLateUpdateSystem,
317	            new CursorDrawPrepSystem(_world),
318	        };
319	        if (editorOpDriver != null) systems.Add(editorOpDriver); // after cursor late-update: final word
320	
321	        return new SequentialSystem<GameState>(systems.ToArray());
322	    }
323	
324	    /// <summary>
325	    /// Wires a toolbar <see cref="EditorToolbarAction"/> to the screen's concrete behaviour, using the
326	    /// SAME shared instances the rest of the editor uses (no second <c>EditorHistory</c> / serializer).
327	    /// Tool-select + snap-toggle mutate the single <see cref="_gizmoState"/> entity that
328	    /// <c>GizmoSystem</c> reads; Save writes through <see cref="SceneWriter"/> with the live camera +
329	    /// layers; Load publishes a <see cref="LoadSceneRequest"/> the registered <c>SceneReaderSystem</c>
330	    /// handles; Undo/Redo drive the shared history.
331	    /// </summary>
332	    private void DispatchToolbarAction(EditorToolbarAction action)
333	    {
334	        switch (action)
335	        {
336	            case EditorToolbarAction.ToolMove: SetGizmoTool(GizmoTool.Move); break;
337	            case EditorToolbarAction.ToolRotate: SetGizmoTool(GizmoTool.Rotate); break;
338	            case EditorToolbarAction.ToolScale: SetGizmoTool(GizmoTool.Scale); break;
339	            case EditorToolbarAction.ToggleSnap: ToggleGizmoSnap(); break;
340	            case EditorToolbarAction.Save:
341	                new SceneWriter(_sceneSerializer).Save(_world, SceneFileName, _camera, _layers);
342	                break;
343	            case EditorToolbarAction.Load:
344	                _world.Publish(new LoadSceneRequest(SceneFileName, fromContent: false));
345	                break;
346	            case EditorToolbarAction.Undo: _history.Undo(); break;
347	            case EditorToolbarAction.Redo: _history.Redo(); break;
348	        }
349	    }
350	
351	    private void SetGizmoTool(GizmoTool tool)
352	    {
353	        if (!_gizmoState.IsAlive) return;
354	        ref var state = ref _gizmoState.Get<GizmoStateComponent>();
355	        state.Tool = tool;
356	    }
357	
358	    private void ToggleGizmoSnap()
359	    {
360	        if (!_gizmoState.IsAlive) return;
361	        ref var state = ref _gizmoState.Get<GizmoStateComponent>();
362	        state.SnapEnabled = !state.SnapEnabled;
363	    }
364	
365	    private SequentialSystem<GameState> CreateDrawSystem()
366	    {
367	        var pixelPerfectRendering = SettingsManager.Instance.Settings.PixelPerfectRendering;
368	
369	        var prepDrawSystems = new SequentialSystem<GameState>(
370	            new CullingSystem(_world, _camera),
371	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering),
372	            new YSortSystem(_world, _camera, _layers),
373	            new TextPrepSystem(_world, pixelPerfectRendering),
374	            new MeshPrepSystem(_world),
375	            new ColliderDebugSystem(_world),
376	            new SpriteDebugSystem(_world)
377	        );
378	
379	        var mainPass = new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
380	            RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera);
381	        var uiPass = new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
382	            RenderTargetID.UI, _renderTargets[RenderTargetID.UI]);
383	        var hudPass = new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
384	            RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]);
385	
386	        var finalDrawToScreenSystem = new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
387	        {
388	            RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
389	            RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
390	            RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
391	        });
392	
393	        var debugDir = PlatformServices.Current.GetEnvironmentVariable("MONODREAMS_DEBUG_DIR")
394	            ?? PlatformServices.Current.CombinePath(PlatformServices.Current.BaseDirectory, "debug");
395	        var replayPlan = InputReplayPlan.TryLoad(debugDir);
396	        var screenshotSystem = new ScreenshotCaptureSystem(_graphicsDevice, captureIntervalSeconds: 2.0f, debugDir)
397	        {
398	            IsEnabled = replayPlan?.Screenshots ?? false
399	        };
400	
401	        // Selection runs at the END of the draw pipeline so it reads the FINAL post-YSort
402	        // DrawComponent.LayerDepth computed THIS frame (YSortSystem above ran first). The cursor's
403	        // click edge (set in the update phase) survives into the draw call, so picking is in-frame.
404	        var selectionSystem = new SelectionSystem(_world);
405	
406	        return new SequentialSystem<GameState>(
407	            prepDrawSystems,
408	            selectionSystem,   // after YSort, before/independent of render; Edit-guarded
409	            mainPass,
410	            uiPass,
411	            hudPass,
412	            finalDrawToScreenSystem,
413	            screenshotSystem
414	        );
415	    }
416	
417	    public void Dispose()
418	    {
419	        UpdateSystem.Dispose();
420	        DrawSystem.Dispose();
421	        GC.SuppressFinalize(this);
422	    }
423	}
